import concurrent.futures, json, subprocess
jobs = {
 'profiles': ['kernel','profiles','list','--project','Default','--per-page','100','--page','1','--output','json'],
 'browsers': ['kernel','browsers','list','--project','Default','--limit','100','--offset','0','--status','active','--output','json']
}
def run(item):
 label, cmd = item
 p=subprocess.run(cmd,capture_output=True,text=True)
 if p.returncode:
  return {'kind':label,'exit_code':p.returncode,'error':p.stderr[:1500]}
 data=json.loads(p.stdout)
 if isinstance(data,dict):
  rows=next((v for v in data.values() if isinstance(v,list)),[])
  meta={k:v for k,v in data.items() if k in ('total','total_count','count','page','per_page','has_more','next_page')}
  keys=list(data)
 else:
  rows=data; meta={}; keys=None
 fields=('id','name','created_at','updated_at','last_used_at') if label=='profiles' else ('session_id','name','created_at','deleted_at','timeout_seconds','profile_save_changes','status')
 safe=[]
 for row in rows:
  record={k:row[k] for k in fields if k in row}
  if label=='browsers':
   record['profile']={k:row['profile'][k] for k in ('id','name') if k in row['profile']} if isinstance(row.get('profile'),dict) else None
  safe.append(record)
 return {'kind':label,'top_level_keys':keys,'metadata':meta,'returned_count':len(rows),'rows':safe}
with concurrent.futures.ThreadPoolExecutor() as pool:
 for result in pool.map(run,jobs.items()):
  print(json.dumps(result,indent=2))
